notify pgrst, 'reload schema';


-- ---------------------------------------------------------------------
-- fitment-verification.sql
-- ---------------------------------------------------------------------
-- =====================================================================
-- MIVO fitment levels: MIVO-verified / seller-listed / unverified
-- Run once in Supabase → SQL Editor. Safe to re-run.
--
-- MIVO Direct parts are always treated as verified. Another shop's part is
-- verified only after MIVO staff check its fitment list. If the vehicle
-- list changes afterwards (by anyone other than MIVO), the check resets.
-- =====================================================================

begin;

alter table public.products add column if not exists fitment_verified boolean not null default false;
alter table public.products add column if not exists fitment_verified_at timestamptz;
alter table public.products add column if not exists fitment_verified_by uuid references auth.users(id) on delete set null;

-- Storefront may read the flag (products use column grants on some setups).
do $$ begin
  grant select (fitment_verified) on public.products to anon, authenticated;
exception when others then null; end $$;

create or replace function public.admin_set_fitment_verified(p_product_id uuid, p_verified boolean)
returns void language plpgsql security definer set search_path = public as $$
begin
  if not public.is_admin() then raise exception 'Only MIVO can verify fitment'; end if;
  update public.products
     set fitment_verified = coalesce(p_verified, false),
         fitment_verified_at = case when p_verified then now() end,
         fitment_verified_by = case when p_verified then auth.uid() end
   where id = p_product_id;
end;
$$;
revoke all on function public.admin_set_fitment_verified(uuid, boolean) from public, anon;
grant execute on function public.admin_set_fitment_verified(uuid, boolean) to authenticated;

-- A seller changing the vehicle list after verification resets it.
create or replace function public.mivo_reset_fitment_verified()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if public.is_admin() then return null; end if;
  update public.products set fitment_verified = false, fitment_verified_at = null, fitment_verified_by = null
   where id = coalesce(new.product_id, old.product_id) and fitment_verified;
  return null;
end;
$$;

drop trigger if exists product_vehicle_fitments_reset_verified on public.product_vehicle_fitments;
create trigger product_vehicle_fitments_reset_verified
  after insert or update or delete on public.product_vehicle_fitments
  for each row execute function public.mivo_reset_fitment_verified();

commit;

-- Make new functions available to the website immediately.
notify pgrst, 'reload schema';


-- ---------------------------------------------------------------------
-- shop-return-address.sql
-- ---------------------------------------------------------------------
-- =====================================================================
-- Shop return address
-- Run once in Supabase → SQL Editor. Safe to re-run.
-- Customers only see a shop's return address on their own approved
-- return request (not public).
-- =====================================================================

begin;

alter table public.sellers add column if not exists return_name text;
alter table public.sellers add column if not exists return_phone text;
alter table public.sellers add column if not exists return_address text;

create or replace function public.admin_save_shop_return_address(p_id uuid, p_name text, p_phone text, p_address text)
returns void language plpgsql security definer set search_path = public as $$
begin
  if not (public.is_admin() or exists (select 1 from public.sellers where id = p_id and owner_id = auth.uid())) then
    raise exception 'Not allowed';
  end if;
  update public.sellers
     set return_name = nullif(btrim(coalesce(p_name, '')), ''),
         return_phone = nullif(btrim(coalesce(p_phone, '')), ''),
         return_address = nullif(btrim(coalesce(p_address, '')), ''),
         updated_at = now()
   where id = p_id;
end;
$$;

create or replace function public.admin_get_shop_return_address(p_id uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  if not (public.is_admin() or exists (select 1 from public.sellers where id = p_id and owner_id = auth.uid())) then
    raise exception 'Not allowed';
  end if;
  return (select jsonb_build_object('name', return_name, 'phone', return_phone, 'address', return_address)
            from public.sellers where id = p_id);
end;
$$;

-- Customer: where to send the item back, only for their approved request.
create or replace function public.return_request_return_address(p_request_id uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare v jsonb;
begin
  select jsonb_build_object('shop', s.shop_name, 'name', s.return_name, 'phone', s.return_phone, 'address', s.return_address)
    into v
  from public.return_requests r join public.sellers s on s.id = r.seller_id
  where r.id = p_request_id and r.customer_id = auth.uid()
    and r.status in ('approved_return', 'returning');
  return v;
end;
$$;

revoke all on function public.admin_save_shop_return_address(uuid, text, text, text) from public, anon;
revoke all on function public.admin_get_shop_return_address(uuid) from public, anon;
revoke all on function public.return_request_return_address(uuid) from public, anon;
grant execute on function public.admin_save_shop_return_address(uuid, text, text, text) to authenticated;
grant execute on function public.admin_get_shop_return_address(uuid) to authenticated;
grant execute on function public.return_request_return_address(uuid) to authenticated;

commit;

-- Make new functions available to the website immediately.
notify pgrst, 'reload schema';


-- ---------------------------------------------------------------------
-- superadmin.sql
-- ---------------------------------------------------------------------
-- =====================================================================
-- MIVO superadmin
-- Run once in Supabase → SQL Editor. Safe to re-run.
--
-- Makes oonzhenlun@gmail.com the platform superadmin and the owner of the
-- MIVO Direct shop(s). Superadmin is above shop admins: platform-wide
-- settings (subsidies, platform campaigns, messages to sellers) will be
-- limited to this role. The account must already be registered on MIVO.
-- =====================================================================

begin;

create table if not exists public.platform_roles (
  user_id uuid primary key references auth.users(id) on delete cascade,
  role text not null check (role in ('superadmin')),
  created_at timestamptz not null default now()
);
alter table public.platform_roles enable row level security;
revoke all on public.platform_roles from anon, authenticated;

create or replace function public.is_superadmin()
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.platform_roles where user_id = auth.uid() and role = 'superadmin');
$$;
revoke all on function public.is_superadmin() from public, anon;
grant execute on function public.is_superadmin() to authenticated;

do $$
declare v_user uuid;
begin
  select id into v_user from auth.users where lower(email) = 'oonzhenlun@gmail.com';
  if v_user is null then
    raise notice 'oonzhenlun@gmail.com has not registered yet. Sign up on MIVO first, then run this file again.';
    return;
  end if;

  insert into public.platform_roles (user_id, role) values (v_user, 'superadmin')
  on conflict (user_id) do update set role = 'superadmin';

  update public.sellers set owner_id = v_user where tier = 'direct' and owner_id is distinct from v_user;

  if not exists (select 1 from pg_proc where proname = 'is_admin') then
    raise notice 'is_admin() not found.';
  end if;
  raise notice 'Superadmin set for oonzhenlun@gmail.com (%). MIVO Direct is owned by this account.', v_user;
end $$;

commit;

