-- ---------------------------------------------------------------------
-- seller-centre.sql
-- ---------------------------------------------------------------------
-- =====================================================================
-- MIVO Seller Centre: sellers manage only their own shops
-- Run once in Supabase → SQL Editor, AFTER per-shop-fulfilment.sql,
-- chat.sql and returns.sql. Safe to re-run.
--
-- A seller is a normal account that owns one or more approved shops
-- (sellers.owner_id). These policies are added ON TOP of the existing
-- ones: MIVO admins keep full access; a seller only gains access to rows
-- of their own shops.
-- =====================================================================

begin;

-- Who may act for a shop: MIVO admins and the shop's owner.
create or replace function public.mivo_can_manage_shop(p_seller_id uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select public.is_admin()
      or exists (select 1 from public.sellers s where s.id = p_seller_id and s.owner_id = auth.uid());
$$;

-- Shops the signed-in user owns and may run (approved only).
create or replace function public.my_shop_ids()
returns setof uuid language sql stable security definer set search_path = public as $$
  select id from public.sellers where owner_id = auth.uid() and status = 'approved';
$$;

create or replace function public.is_seller()
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.sellers where owner_id = auth.uid() and status = 'approved');
$$;

-- Seller Centre home: my shops (including pending applications).
create or replace function public.seller_my_shops()
returns table (id uuid, shop_name text, slug text, status text, tier text, logo_url text, commission_rate numeric)
language sql stable security definer set search_path = public as $$
  select s.id, s.shop_name, s.slug, s.status, s.tier, s.logo_url, s.commission_rate
    from public.sellers s where s.owner_id = auth.uid() order by s.created_at;
$$;

grant execute on function public.my_shop_ids() to authenticated;
grant execute on function public.is_seller() to authenticated;
grant execute on function public.seller_my_shops() to authenticated;
grant execute on function public.mivo_can_manage_shop(uuid) to authenticated;

-- ---------------------------------------------------------------------
-- Open a shop: any signed-in user can apply; MIVO approves.
-- ---------------------------------------------------------------------
create or replace function public.seller_apply(p_shop_name text, p_phone text, p_note text)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_id uuid;
  v_slug text;
  v_email text;
  v_phone text := nullif(btrim(coalesce(p_phone, '')), '');
  v_cols text := 'owner_id, shop_name, slug, status, tier, description';
  v_vals text := '$1, $2, $3, ''pending'', ''standard'', $4';
  c record;
begin
  if auth.uid() is null then raise exception 'Please sign in'; end if;
  if coalesce(btrim(p_shop_name), '') = '' then raise exception 'Shop name is required'; end if;
  if (select count(*) from public.sellers where owner_id = auth.uid() and status = 'pending') >= 3 then
    raise exception 'You already have shop applications waiting for approval';
  end if;
  v_slug := nullif(lower(regexp_replace(btrim(p_shop_name), '[^a-zA-Z0-9]+', '-', 'g')), '');
  if exists (select 1 from public.sellers where lower(slug) = v_slug) then
    v_slug := v_slug || '-' || substr(md5(gen_random_uuid()::text), 1, 4);
  end if;
  select email into v_email from auth.users where id = auth.uid();

  -- Older setups may have extra required columns (contact, bank, business
  -- details). Fill them with the applicant's phone/email or a blank value;
  -- MIVO completes them when approving.
  for c in
    select column_name, data_type, udt_schema, udt_name
      from information_schema.columns
     where table_schema = 'public' and table_name = 'sellers'
       and is_nullable = 'NO' and column_default is null and is_generated = 'NEVER' and identity_generation is null
       and column_name not in ('id', 'owner_id', 'shop_name', 'slug', 'status', 'tier', 'description')
  loop
    v_cols := v_cols || ', ' || quote_ident(c.column_name);
    v_vals := v_vals || ', ' || case
      when c.column_name ~* 'email' then quote_literal(coalesce(v_email, ''))
      when c.column_name ~* 'phone|mobile|contact' then quote_literal(coalesce(v_phone, ''))
      when c.column_name ~* 'name' then quote_literal(btrim(p_shop_name))
      when c.data_type in ('text', 'character varying', 'character') then quote_literal('')
      when c.data_type in ('integer', 'bigint', 'smallint', 'numeric', 'real', 'double precision') then '0'
      when c.data_type = 'boolean' then 'false'
      when c.data_type like 'timestamp%' or c.data_type = 'date' then 'now()'
      when c.data_type = 'jsonb' then quote_literal('{}') || '::jsonb'
      when c.data_type = 'ARRAY' then quote_literal('{}')
      when c.data_type = 'USER-DEFINED' then format('(enum_range(null::%I.%I))[1]', c.udt_schema, c.udt_name)
      else 'null' end;
  end loop;

  execute format('insert into public.sellers (%s) values (%s) returning id', v_cols, v_vals)
    into v_id using auth.uid(), btrim(p_shop_name), v_slug, nullif(btrim(coalesce(p_note, '')), '');

  -- Phone on the shop record, when the column exists.
  begin
    execute 'update public.sellers set phone = coalesce(nullif(phone, ''''), $1) where id = $2' using v_phone, v_id;
  exception when undefined_column then null;
  end;
  return v_id;
end;
$$;

revoke all on function public.seller_apply(text, text, text) from public, anon;
grant execute on function public.seller_apply(text, text, text) to authenticated;

-- sellers.status may be text or an enum: convert text to the column's type.
create or replace function public.mivo_as_shop_status(p_status text)
returns public.sellers.status%type language sql stable as $$
  select (jsonb_populate_record(null::public.sellers, jsonb_build_object('status', p_status))).status;
$$;

-- MIVO: approve / suspend a shop.
create or replace function public.admin_set_shop_status(p_id uuid, p_status text)
returns void language plpgsql security definer set search_path = public as $$
begin
  if not public.is_admin() then raise exception 'Only MIVO can change a shop''s status'; end if;
  if p_status not in ('approved', 'pending', 'suspended', 'rejected') then raise exception 'Unknown status'; end if;
  update public.sellers
     set status = public.mivo_as_shop_status(p_status),
         approved_at = case when p_status = 'approved' then coalesce(approved_at, now()) else approved_at end,
         updated_at = now()
   where id = p_id;
exception when check_violation then
  raise exception 'Status % is not allowed by the sellers table', p_status;
end;
$$;
revoke all on function public.admin_set_shop_status(uuid, text) from public, anon;
grant execute on function public.admin_set_shop_status(uuid, text) to authenticated;

-- Seller: edit own shop's storefront details (status/tier/commission stay protected).
create or replace function public.seller_save_shop(p_id uuid, p_tagline text, p_description text, p_logo_url text, p_banner_url text)
returns void language plpgsql security definer set search_path = public as $$
begin
  if not exists (select 1 from public.sellers where id = p_id and owner_id = auth.uid()) and not public.is_admin() then
    raise exception 'Not your shop';
  end if;
  update public.sellers
     set tagline = nullif(btrim(coalesce(p_tagline, '')), ''),
         description = nullif(btrim(coalesce(p_description, '')), ''),
         logo_url = nullif(btrim(coalesce(p_logo_url, '')), ''),
         banner_url = nullif(btrim(coalesce(p_banner_url, '')), ''),
         updated_at = now()
   where id = p_id;
end;
$$;
revoke all on function public.seller_save_shop(uuid, text, text, text, text) from public, anon;
grant execute on function public.seller_save_shop(uuid, text, text, text, text) to authenticated;

-- ---------------------------------------------------------------------
-- Row access for sellers (added to existing policies).
-- ---------------------------------------------------------------------
do $$
declare t text;
begin
  -- products / variants: full management of own shop's rows
  foreach t in array array['products', 'product_variants'] loop
    execute format('drop policy if exists "sellers manage own %1$s" on public.%1$I', t);
    execute format(
      'create policy "sellers manage own %1$s" on public.%1$I for all to authenticated
         using (seller_id in (select public.my_shop_ids()))
         with check (seller_id in (select public.my_shop_ids()))', t);
  end loop;
end $$;

drop policy if exists "sellers manage own product images" on public.product_images;
create policy "sellers manage own product images" on public.product_images for all to authenticated
  using (exists (select 1 from public.products p where p.id = product_id and p.seller_id in (select public.my_shop_ids())))
  with check (exists (select 1 from public.products p where p.id = product_id and p.seller_id in (select public.my_shop_ids())));

drop policy if exists "sellers manage own fitments" on public.product_vehicle_fitments;
create policy "sellers manage own fitments" on public.product_vehicle_fitments for all to authenticated
  using (exists (select 1 from public.products p where p.id = product_id and p.seller_id in (select public.my_shop_ids())))
  with check (exists (select 1 from public.products p where p.id = product_id and p.seller_id in (select public.my_shop_ids())));

-- Orders: a seller sees their own shop parcels, items and shipments (not
-- other shops' items, and not the buyer's payment details).
drop policy if exists "sellers read own seller orders" on public.seller_orders;
create policy "sellers read own seller orders" on public.seller_orders for select to authenticated
  using (seller_id in (select public.my_shop_ids()));

drop policy if exists "sellers read own order items" on public.order_items;
create policy "sellers read own order items" on public.order_items for select to authenticated
  using (seller_id in (select public.my_shop_ids()));

drop policy if exists "sellers read own shipments" on public.shipments;
create policy "sellers read own shipments" on public.shipments for select to authenticated
  using (exists (select 1 from public.seller_orders so where so.id = seller_order_id and so.seller_id in (select public.my_shop_ids())));

-- Seller order list with what a seller needs from the parent order.
-- Dropped first: checkout-per-shop.sql later adds a column to the result.
drop function if exists public.seller_parcels(uuid);
create function public.seller_parcels(p_seller_id uuid default null)
returns table (
  seller_order_id uuid, seller_id uuid, order_number text, order_status text, payment_status text,
  parcel_status text, subtotal numeric, shipping_address jsonb, customer_note text, created_at timestamptz,
  paid_at timestamptz, courier_name text, tracking_number text)
language sql stable security definer set search_path = public as $$
  select so.id, so.seller_id, o.order_number, o.status::text, o.payment_status::text,
         greatest_status.status, so.subtotal, so.shipping_address, so.customer_note, o.created_at,
         o.paid_at, sh.courier_name, sh.tracking_number
    from public.seller_orders so
    join public.orders o on o.id = so.order_id
    cross join lateral (
      select case
        when public.mivo_fulfilment_rank(so.status::text) >= public.mivo_fulfilment_rank(o.status::text) then so.status::text
        else o.status::text end as status
    ) greatest_status
    left join lateral (
      select courier_name, tracking_number from public.shipments s
       where s.seller_order_id = so.id order by s.created_at limit 1
    ) sh on true
   where so.seller_id in (select public.my_shop_ids())
     and (p_seller_id is null or so.seller_id = p_seller_id)
   order by o.created_at desc
   limit 500;
$$;
grant execute on function public.seller_parcels(uuid) to authenticated;

-- Sellers can't mark their own fitment as MIVO-verified.
create or replace function public.mivo_guard_product_verification()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null or public.is_admin() then return new; end if;
  if tg_op = 'INSERT' then
    new.fitment_verified := false;
    new.fitment_verified_at := null;
    new.fitment_verified_by := null;
  else
    new.fitment_verified := old.fitment_verified;
    new.fitment_verified_at := old.fitment_verified_at;
    new.fitment_verified_by := old.fitment_verified_by;
  end if;
  return new;
end;
$$;

do $$ begin
  if exists (select 1 from information_schema.columns
              where table_schema = 'public' and table_name = 'products' and column_name = 'fitment_verified') then
    drop trigger if exists products_guard_verification on public.products;
    create trigger products_guard_verification before insert or update on public.products
      for each row execute function public.mivo_guard_product_verification();
  else
    raise notice 'Run fitment-verification.sql first, then this file again, to protect the verified flag.';
  end if;
end $$;

-- Product images: sellers upload into their own shops' folders.
drop policy if exists "MIVO sellers upload images to own shops" on storage.objects;
create policy "MIVO sellers upload images to own shops" on storage.objects for insert to authenticated
  with check (bucket_id = 'product-images'
              and (storage.foldername(name))[1] in (select s::text from public.my_shop_ids() as s));
drop policy if exists "MIVO sellers change images of own shops" on storage.objects;
create policy "MIVO sellers change images of own shops" on storage.objects for update to authenticated
  using (bucket_id = 'product-images'
         and (storage.foldername(name))[1] in (select s::text from public.my_shop_ids() as s));
drop policy if exists "MIVO sellers delete images of own shops" on storage.objects;
create policy "MIVO sellers delete images of own shops" on storage.objects for delete to authenticated
  using (bucket_id = 'product-images'
         and (storage.foldername(name))[1] in (select s::text from public.my_shop_ids() as s));

commit;

-- Make new functions available to the website immediately.
notify pgrst, 'reload schema';


-- ---------------------------------------------------------------------
-- seller-onboarding.sql
-- ---------------------------------------------------------------------
-- =====================================================================
-- MIVO seller onboarding (marketplace style): business details, bank
-- account and documents (IC, SSM, bank statement) for review.
-- Run once in Supabase → SQL Editor, AFTER seller-centre.sql. Safe to re-run.
--
-- Documents go to a PRIVATE storage bucket; only the applicant and MIVO
-- admins can open them. MIVO approves, rejects or asks for more info.
-- =====================================================================

begin;

create table if not exists public.seller_applications (
  id uuid primary key default gen_random_uuid(),
  seller_id uuid not null references public.sellers(id) on delete cascade,
  owner_id uuid not null references auth.users(id) on delete cascade,
  seller_type text not null check (seller_type in ('individual', 'business')),
  legal_name text not null,
  ic_number text,
  business_reg_no text,
  tin text,
  sst_no text,
  phone text not null,
  email text,
  business_address text not null,
  pickup_address jsonb not null,
  bank_name text not null,
  bank_account_name text not null,
  bank_account_no text not null,
  documents jsonb not null default '{}'::jsonb,   -- {ic_front, ic_back, ssm, bank_statement, other[]} storage paths
  categories text,
  status text not null default 'submitted' check (status in ('submitted', 'more_info', 'approved', 'rejected')),
  admin_note text,
  reviewed_by uuid references auth.users(id) on delete set null,
  reviewed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (seller_id)
);
alter table public.seller_applications enable row level security;
revoke all on public.seller_applications from anon, authenticated;

drop policy if exists "applications: owner or admin read" on public.seller_applications;
create policy "applications: owner or admin read" on public.seller_applications for select to authenticated
  using (owner_id = auth.uid() or public.is_admin());
grant select on public.seller_applications to authenticated;

-- Submit (or resubmit after "more info") an application.
create or replace function public.seller_submit_application(p jsonb)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_seller uuid;
  v_app public.seller_applications%rowtype;
  v_type text := p->>'seller_type';
  v_docs jsonb := coalesce(p->'documents', '{}'::jsonb);
begin
  if auth.uid() is null then raise exception 'Please sign in'; end if;
  if v_type not in ('individual', 'business') then raise exception 'Choose individual or business seller'; end if;
  if coalesce(btrim(p->>'shop_name'), '') = '' then raise exception 'Shop name is required'; end if;
  if coalesce(btrim(p->>'legal_name'), '') = '' then raise exception 'Legal name is required'; end if;
  if coalesce(btrim(p->>'phone'), '') = '' then raise exception 'Phone number is required'; end if;
  if coalesce(btrim(p->>'business_address'), '') = '' then raise exception 'Address is required'; end if;
  if coalesce(btrim(p->>'bank_name'), '') = '' or coalesce(btrim(p->>'bank_account_name'), '') = ''
     or coalesce(btrim(p->>'bank_account_no'), '') = '' then
    raise exception 'Bank details are required';
  end if;
  if v_type = 'individual' and (coalesce(btrim(p->>'ic_number'), '') = '' or v_docs->>'ic_front' is null or v_docs->>'ic_back' is null) then
    raise exception 'IC number and both sides of your IC are required';
  end if;
  if v_type = 'business' and (coalesce(btrim(p->>'business_reg_no'), '') = '' or v_docs->>'ssm' is null) then
    raise exception 'SSM registration number and SSM certificate are required';
  end if;
  if v_docs->>'bank_statement' is null then raise exception 'Upload a bank statement header showing the account name'; end if;
  -- Documents must be the applicant's own uploads.
  if exists (select 1 from jsonb_each_text(v_docs - 'other') d where split_part(d.value, '/', 1) <> auth.uid()::text) then
    raise exception 'Invalid document';
  end if;

  -- Resubmission of an existing application?
  select * into v_app from public.seller_applications
   where owner_id = auth.uid() and (p->>'application_id') is not null and id = (p->>'application_id')::uuid;

  if found then
    if v_app.status not in ('more_info', 'rejected') then raise exception 'This application is already %', v_app.status; end if;
    v_seller := v_app.seller_id;
    update public.sellers set shop_name = btrim(p->>'shop_name'), status = 'pending', updated_at = now() where id = v_seller;
  else
    v_seller := public.seller_apply(p->>'shop_name', p->>'phone', p->>'categories');
  end if;

  insert into public.seller_applications as a (
    seller_id, owner_id, seller_type, legal_name, ic_number, business_reg_no, tin, sst_no, phone, email,
    business_address, pickup_address, bank_name, bank_account_name, bank_account_no, documents, categories, status)
  values (
    v_seller, auth.uid(), v_type, btrim(p->>'legal_name'), nullif(btrim(p->>'ic_number'), ''),
    nullif(btrim(p->>'business_reg_no'), ''), nullif(btrim(p->>'tin'), ''), nullif(btrim(p->>'sst_no'), ''),
    btrim(p->>'phone'), (select email from auth.users where id = auth.uid()),
    btrim(p->>'business_address'), coalesce(p->'pickup_address', '{}'::jsonb),
    btrim(p->>'bank_name'), btrim(p->>'bank_account_name'), regexp_replace(p->>'bank_account_no', '\s', '', 'g'),
    v_docs, nullif(btrim(p->>'categories'), ''), 'submitted')
  on conflict (seller_id) do update set
    seller_type = excluded.seller_type, legal_name = excluded.legal_name, ic_number = excluded.ic_number,
    business_reg_no = excluded.business_reg_no, tin = excluded.tin, sst_no = excluded.sst_no, phone = excluded.phone,
    business_address = excluded.business_address, pickup_address = excluded.pickup_address,
    bank_name = excluded.bank_name, bank_account_name = excluded.bank_account_name,
    bank_account_no = excluded.bank_account_no, documents = excluded.documents, categories = excluded.categories,
    status = 'submitted', updated_at = now();

  return v_seller;
end;
$$;

-- MIVO: review an application.
create or replace function public.admin_review_application(p_id uuid, p_decision text, p_note text)
returns void language plpgsql security definer set search_path = public as $$
declare a public.seller_applications%rowtype;
begin
  if not public.is_admin() then raise exception 'Only MIVO can review applications'; end if;
  if p_decision not in ('approved', 'rejected', 'more_info') then raise exception 'Unknown decision'; end if;
  if p_decision <> 'approved' and coalesce(btrim(p_note), '') = '' then
    raise exception 'Tell the seller why (shown to them)';
  end if;
  select * into a from public.seller_applications where id = p_id for update;
  if not found then raise exception 'Application not found'; end if;

  update public.seller_applications
     set status = p_decision, admin_note = nullif(btrim(coalesce(p_note, '')), ''),
         reviewed_by = auth.uid(), reviewed_at = now(), updated_at = now()
   where id = p_id;

  if p_decision = 'approved' then
    update public.sellers set status = 'approved', approved_at = coalesce(approved_at, now()), updated_at = now()
     where id = a.seller_id;
    -- Copy contact/bank details onto the shop record where those columns exist.
    begin
      execute 'update public.sellers set phone = $1 where id = $2' using a.phone, a.seller_id;
    exception when undefined_column then null; end;
    begin
      execute 'update public.sellers set bank_name = $1, bank_account_name = $2, bank_account_number = $3 where id = $4'
        using a.bank_name, a.bank_account_name, a.bank_account_no, a.seller_id;
    exception when undefined_column then null; end;
  elsif p_decision = 'rejected' then
    update public.sellers set status = 'rejected', updated_at = now() where id = a.seller_id;
  end if;
exception when check_violation then
  raise exception 'The sellers table does not allow status %', p_decision;
end;
$$;

revoke all on function public.seller_submit_application(jsonb) from public, anon;
revoke all on function public.admin_review_application(uuid, text, text) from public, anon;
grant execute on function public.seller_submit_application(jsonb) to authenticated;
grant execute on function public.admin_review_application(uuid, text, text) to authenticated;

-- Private documents bucket: applicants write to their own folder.
insert into storage.buckets (id, name, public) values ('seller-documents', 'seller-documents', false)
on conflict (id) do nothing;

drop policy if exists "MIVO seller documents upload" on storage.objects;
create policy "MIVO seller documents upload" on storage.objects for insert to authenticated
  with check (bucket_id = 'seller-documents' and (storage.foldername(name))[1] = auth.uid()::text);

drop policy if exists "MIVO seller documents read" on storage.objects;
create policy "MIVO seller documents read" on storage.objects for select to authenticated
  using (bucket_id = 'seller-documents' and ((storage.foldername(name))[1] = auth.uid()::text or public.is_admin()));

commit;

-- Make new functions available to the website immediately.
notify pgrst, 'reload schema';


-- ---------------------------------------------------------------------
-- seller-customer-names.sql
-- ---------------------------------------------------------------------
-- =====================================================================
-- MIVO: let sellers see who they are dealing with.
-- Run once in Supabase → SQL Editor, AFTER seller-centre.sql, chat.sql
-- and returns.sql. Safe to re-run.
--
-- Sellers can't read the profiles or orders tables directly, so their
-- returns and chat screens showed "Customer" and "—". This returns only
-- the name and avatar of customers who bought from, chatted with or asked
-- for a return from the caller's own shops, and the order numbers of
-- those shops' orders. Emails and phone numbers are not included.
-- =====================================================================

begin;

create or replace function public.seller_customer_info(p_customer_ids uuid[], p_order_ids uuid[])
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_people jsonb;
  v_orders jsonb;
begin
  if auth.uid() is null then return jsonb_build_object('people', '[]'::jsonb, 'orders', '[]'::jsonb); end if;

  select coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'full_name', p.full_name, 'avatar_url', to_jsonb(p) ->> 'avatar_url')), '[]'::jsonb)
    into v_people
    from public.profiles p
   where p.id = any(coalesce(p_customer_ids, '{}'))
     and (
       public.is_admin()
       or exists (select 1 from public.chat_conversations c where c.customer_id = p.id and c.seller_id in (select public.my_shop_ids()))
       or exists (select 1 from public.return_requests r where r.customer_id = p.id and r.seller_id in (select public.my_shop_ids()))
       or exists (select 1 from public.seller_orders so join public.orders o on o.id = so.order_id
                   where o.user_id = p.id and so.seller_id in (select public.my_shop_ids()))
     );

  select coalesce(jsonb_agg(jsonb_build_object('id', o.id, 'order_number', o.order_number)), '[]'::jsonb)
    into v_orders
    from public.orders o
   where o.id = any(coalesce(p_order_ids, '{}'))
     and (
       public.is_admin()
       or exists (select 1 from public.seller_orders so where so.order_id = o.id and so.seller_id in (select public.my_shop_ids()))
     );

  return jsonb_build_object('people', v_people, 'orders', v_orders);
end;
$$;

revoke all on function public.seller_customer_info(uuid[], uuid[]) from public, anon;
grant execute on function public.seller_customer_info(uuid[], uuid[]) to authenticated;

commit;

-- Make new functions available to the website immediately.
notify pgrst, 'reload schema';


-- ---------------------------------------------------------------------
-- checkout-per-shop.sql
-- ---------------------------------------------------------------------
-- =====================================================================
-- MIVO checkout per shop (marketplace style)
-- Run once in Supabase → SQL Editor, AFTER seller-centre.sql. Safe to re-run.
-- With EasyParcel connected, shipping is priced live from EasyParcel instead
-- (see /api/shipping/quote); MIVO's shipping rules are the fallback.
--
-- Each shop packs and ships its own parcel, so the buyer chooses a courier
-- per shop and pays each shop's shipping. This builds on the existing
-- quote_shipping_options() and create_pending_order() (unchanged):
--   * quote_shipping_by_shop()   quotes every shop's items separately.
--   * create_pending_order_by_shop() creates the order as before, then sets
--     the order's shipping to the sum of the chosen per-shop quotes and
--     records each shop's courier (sellers must ship with that courier).
-- The website falls back to the old single-courier checkout until this runs.
-- =====================================================================

begin;

alter table public.seller_orders add column if not exists buyer_courier_code text;
alter table public.seller_orders add column if not exists buyer_courier_name text;
alter table public.seller_orders add column if not exists buyer_shipping_fee numeric(12,2);

-- Rows of quote_shipping_options() as a jsonb array, whatever its return type.
create or replace function public.mivo_quote_options(p_items jsonb, p_state text, p_postcode text)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_set boolean;
  v_result jsonb;
begin
  select p.proretset into v_set
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'quote_shipping_options'
   limit 1;
  if v_set then
    execute 'select coalesce(jsonb_agg(to_jsonb(q)), ''[]''::jsonb) from public.quote_shipping_options($1, $2, $3) q'
      into v_result using p_items, p_state, p_postcode;
  else
    execute 'select to_jsonb(public.quote_shipping_options($1, $2, $3))'
      into v_result using p_items, p_state, p_postcode;
  end if;
  return coalesce(v_result, '[]'::jsonb);
end;
$$;

-- Shipping options for each shop's parcel.
create or replace function public.quote_shipping_by_shop(p_items jsonb, p_state text, p_postcode text)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_group record;
  v_out jsonb := '[]'::jsonb;
begin
  for v_group in
    select v.seller_id, s.shop_name, s.tier,
           jsonb_agg(jsonb_build_object('variant_id', v.id, 'quantity', (i ->> 'quantity')::int)) as items
      from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) i
      join public.product_variants v on v.id = (i ->> 'variant_id')::uuid
      join public.sellers s on s.id = v.seller_id
     group by v.seller_id, s.shop_name, s.tier
     order by (s.tier = 'direct') desc, s.shop_name
  loop
    v_out := v_out || jsonb_build_array(jsonb_build_object(
      'seller_id', v_group.seller_id,
      'shop_name', v_group.shop_name,
      'tier', v_group.tier,
      'options', public.mivo_quote_options(v_group.items, p_state, p_postcode)
    ));
  end loop;
  return v_out;
end;
$$;

-- MIVO-funded free shipping (superadmin): during a promotion, orders that
-- reach the minimum spend get shipping paid by MIVO, up to a cap per order.
create table if not exists public.shipping_promotions (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  starts_at timestamptz not null,
  ends_at timestamptz not null,
  min_spend numeric(12,2) not null default 0,
  max_subsidy numeric(12,2),            -- per order; null = all shipping
  active boolean not null default true,
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  check (ends_at > starts_at)
);
alter table public.shipping_promotions enable row level security;
revoke all on public.shipping_promotions from anon, authenticated;

alter table public.orders add column if not exists shipping_subsidy numeric(12,2) not null default 0;
alter table public.orders add column if not exists shipping_promotion_id uuid references public.shipping_promotions(id) on delete set null;

-- The promotion running now (shown at checkout).
create or replace function public.active_shipping_promotion()
returns jsonb language sql stable security definer set search_path = public as $$
  select to_jsonb(p) - 'created_by' - 'created_at'
    from public.shipping_promotions p
   where p.active and now() between p.starts_at and p.ends_at
   order by p.max_subsidy desc nulls first, p.min_spend
   limit 1;
$$;
grant execute on function public.active_shipping_promotion() to anon, authenticated;

create or replace function public.platform_shipping_promotions()
returns setof public.shipping_promotions language plpgsql stable security definer set search_path = public as $$
begin
  if not public.is_superadmin() then raise exception 'Only the MIVO superadmin can manage free shipping'; end if;
  return query select * from public.shipping_promotions order by starts_at desc limit 200;
end;
$$;

create or replace function public.platform_save_shipping_promotion(
  p_name text, p_starts_at timestamptz, p_ends_at timestamptz, p_min_spend numeric, p_max_subsidy numeric
)
returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid;
begin
  if not public.is_superadmin() then raise exception 'Only the MIVO superadmin can manage free shipping'; end if;
  if coalesce(btrim(p_name), '') = '' then raise exception 'Give the promotion a name'; end if;
  if p_ends_at <= p_starts_at then raise exception 'The end must be after the start'; end if;
  insert into public.shipping_promotions (name, starts_at, ends_at, min_spend, max_subsidy, created_by)
  values (btrim(p_name), p_starts_at, p_ends_at, greatest(coalesce(p_min_spend, 0), 0),
          case when p_max_subsidy > 0 then p_max_subsidy end, auth.uid())
  returning id into v_id;
  return v_id;
end;
$$;

create or replace function public.platform_end_shipping_promotion(p_id uuid)
returns void language plpgsql security definer set search_path = public as $$
begin
  if not public.is_superadmin() then raise exception 'Only the MIVO superadmin can manage free shipping'; end if;
  update public.shipping_promotions set active = false where id = p_id;
end;
$$;

revoke all on function public.platform_shipping_promotions() from public, anon;
revoke all on function public.platform_save_shipping_promotion(text, timestamptz, timestamptz, numeric, numeric) from public, anon;
revoke all on function public.platform_end_shipping_promotion(uuid) from public, anon;
grant execute on function public.platform_shipping_promotions() to authenticated;
grant execute on function public.platform_save_shipping_promotion(text, timestamptz, timestamptz, numeric, numeric) to authenticated;
grant execute on function public.platform_end_shipping_promotion(uuid) to authenticated;

-- Shipping prices quoted live from EasyParcel at checkout (server-side, see
-- /api/shipping/quote). Valid 30 minutes; the order uses them as-is.
create table if not exists public.checkout_shipping_quotes (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  items_key text not null,               -- sorted "variant:qty" list the quote is for
  postcode text not null,
  state text not null,
  shops jsonb not null,                  -- [{seller_id, amount, courier, service_id}]
  created_at timestamptz not null default now(),
  expires_at timestamptz not null default now() + interval '30 minutes'
);
alter table public.checkout_shipping_quotes enable row level security;
revoke all on public.checkout_shipping_quotes from anon, authenticated;

create or replace function public.mivo_items_key(p_items jsonb)
returns text language sql immutable as $$
  select coalesce(string_agg((i ->> 'variant_id') || ':' || (i ->> 'quantity'), ',' order by i ->> 'variant_id'), '')
    from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) i;
$$;

-- Create the order with shipping per shop: from a live EasyParcel quote
-- (p_quote_id) or, without one, from MIVO's shipping rules (p_couriers:
-- {"<seller_id>": "<courier_code>"}).
drop function if exists public.create_pending_order_by_shop(jsonb, jsonb, text, uuid, jsonb);
create or replace function public.create_pending_order_by_shop(
  p_items jsonb,
  p_shipping_address jsonb,
  p_customer_note text default null,
  p_voucher_id uuid default null,
  p_couriers jsonb default '{}'::jsonb,
  p_quote_id uuid default null
)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_quotes jsonb;
  v_shop jsonb;
  v_choice jsonb;
  v_code text;
  v_first_code text;
  v_shipping numeric := 0;
  v_result jsonb;
  v_order public.orders%rowtype;
  v_discount numeric;
  v_voucher record;
  v_live public.checkout_shipping_quotes%rowtype;
  v_fees jsonb := '[]'::jsonb;   -- [{seller_id, fee, courier_code, courier_name}]
  v_promo public.shipping_promotions%rowtype;
  v_subsidy numeric := 0;
begin
  if auth.uid() is null then raise exception 'Please sign in'; end if;

  v_quotes := public.quote_shipping_by_shop(p_items, p_shipping_address ->> 'state', p_shipping_address ->> 'postcode');
  if jsonb_array_length(v_quotes) = 0 then raise exception 'Your cart is empty'; end if;

  if p_quote_id is not null then
    -- Live EasyParcel prices quoted for this cart and address.
    select * into v_live from public.checkout_shipping_quotes
     where id = p_quote_id and user_id = auth.uid();
    if not found or v_live.expires_at < now() then
      raise exception 'Shipping price expired. Please refresh the checkout page.';
    end if;
    if v_live.items_key <> public.mivo_items_key(p_items)
       or v_live.postcode <> coalesce(p_shipping_address ->> 'postcode', '')
       or v_live.state <> coalesce(p_shipping_address ->> 'state', '') then
      raise exception 'Your cart or address changed. Please refresh the checkout page.';
    end if;
    for v_shop in select * from jsonb_array_elements(v_quotes) loop
      select q into v_choice from jsonb_array_elements(v_live.shops) q
       where q ->> 'seller_id' = v_shop ->> 'seller_id' limit 1;
      if v_choice is null then raise exception 'Shipping price missing for %', v_shop ->> 'shop_name'; end if;
      v_shipping := v_shipping + coalesce((v_choice ->> 'amount')::numeric, 0);
      v_fees := v_fees || jsonb_build_array(jsonb_build_object(
        'seller_id', v_shop ->> 'seller_id', 'fee', (v_choice ->> 'amount')::numeric,
        'courier_code', v_choice ->> 'service_id', 'courier_name', v_choice ->> 'courier'));
      -- create_pending_order still needs one of MIVO's courier codes.
      v_first_code := coalesce(v_first_code, v_shop -> 'options' -> 0 ->> 'courier_code');
      v_choice := null;
    end loop;
  else
    -- MIVO's own shipping rules: one courier per shop.
    for v_shop in select * from jsonb_array_elements(v_quotes) loop
      v_code := p_couriers ->> (v_shop ->> 'seller_id');
      v_choice := null;
      select o into v_choice from jsonb_array_elements(v_shop -> 'options') o
       where o ->> 'courier_code' = v_code limit 1;
      if v_choice is null then
        raise exception 'Choose a courier for %', v_shop ->> 'shop_name';
      end if;
      v_first_code := coalesce(v_first_code, v_code);
      v_shipping := v_shipping + coalesce((v_choice ->> 'shipping_amount')::numeric, 0);
      v_fees := v_fees || jsonb_build_array(jsonb_build_object(
        'seller_id', v_shop ->> 'seller_id', 'fee', (v_choice ->> 'shipping_amount')::numeric,
        'courier_code', v_code, 'courier_name', v_choice ->> 'courier_name'));
    end loop;
  end if;

  -- The existing checkout does stock, prices, vouchers and the order itself.
  v_result := public.create_pending_order(
    p_items,
    p_shipping_address || jsonb_build_object('courier_code', v_first_code, 'shop_couriers', p_couriers),
    p_customer_note,
    p_voucher_id
  );

  select * into v_order from public.orders
   where order_number = v_result ->> 'order_number' and user_id = auth.uid()
   for update;
  if not found then raise exception 'Order not found after checkout'; end if;

  -- MIVO free-shipping promotion: MIVO pays shipping (up to the cap) when the
  -- order reaches the minimum spend. The buyer pays only what's left.
  select * into v_promo from public.shipping_promotions
   where active and now() between starts_at and ends_at
   order by max_subsidy desc nulls first, min_spend limit 1;
  if found and coalesce(v_order.subtotal, 0) >= v_promo.min_spend then
    v_subsidy := least(v_shipping, coalesce(v_promo.max_subsidy, v_shipping));
  end if;
  v_shipping := v_shipping - v_subsidy;

  -- Free-shipping vouchers follow the new shipping total.
  v_discount := coalesce(v_order.discount_amount, 0);
  if v_order.voucher_code is not null then
    select discount_type, max_discount into v_voucher
      from public.vouchers where code = v_order.voucher_code limit 1;
    if found and v_voucher.discount_type = 'free_shipping' then
      v_discount := least(v_shipping, coalesce(nullif(v_voucher.max_discount, 0), v_shipping));
    end if;
  end if;

  update public.orders
     set shipping_amount = v_shipping,
         shipping_subsidy = v_subsidy,
         shipping_promotion_id = case when v_subsidy > 0 then v_promo.id end,
         discount_amount = v_discount,
         total_amount = greatest(0, coalesce(subtotal, 0) + v_shipping - v_discount),
         updated_at = now()
   where id = v_order.id;

  -- Each shop's shipping fee (and what it was priced at) on its parcel.
  for v_shop in select * from jsonb_array_elements(v_fees) loop
    update public.seller_orders
       set buyer_courier_code = v_shop ->> 'courier_code',
           buyer_courier_name = v_shop ->> 'courier_name',
           buyer_shipping_fee = (v_shop ->> 'fee')::numeric
     where order_id = v_order.id and seller_id = (v_shop ->> 'seller_id')::uuid;
  end loop;

  if p_quote_id is not null then
    delete from public.checkout_shipping_quotes where id = p_quote_id or expires_at < now() - interval '1 day';
  end if;

  return v_result || jsonb_build_object(
    'shipping_amount', v_shipping,
    'shipping_subsidy', v_subsidy,
    'discount_amount', v_discount,
    'total_amount', greatest(0, coalesce(v_order.subtotal, 0) + v_shipping - v_discount)
  );
end;
$$;

revoke all on function public.mivo_quote_options(jsonb, text, text) from public, anon;
revoke all on function public.quote_shipping_by_shop(jsonb, text, text) from public;
revoke all on function public.create_pending_order_by_shop(jsonb, jsonb, text, uuid, jsonb, uuid) from public, anon;
grant execute on function public.mivo_quote_options(jsonb, text, text) to authenticated;
grant execute on function public.quote_shipping_by_shop(jsonb, text, text) to anon, authenticated;
grant execute on function public.create_pending_order_by_shop(jsonb, jsonb, text, uuid, jsonb, uuid) to authenticated;

-- Seller Centre: include the courier the buyer chose for each parcel.
drop function if exists public.seller_parcels(uuid);
create function public.seller_parcels(p_seller_id uuid default null)
returns table (
  seller_order_id uuid, seller_id uuid, order_number text, order_status text, payment_status text,
  parcel_status text, subtotal numeric, shipping_address jsonb, customer_note text, created_at timestamptz,
  paid_at timestamptz, courier_name text, tracking_number text, buyer_courier_name text)
language sql stable security definer set search_path = public as $$
  select so.id, so.seller_id, o.order_number, o.status::text, o.payment_status::text,
         greatest_status.status, so.subtotal, so.shipping_address, so.customer_note, o.created_at,
         o.paid_at, sh.courier_name, sh.tracking_number,
         coalesce(so.buyer_courier_name, o.shipping_address ->> 'shipping_courier_name', o.shipping_address ->> 'courier_name')
    from public.seller_orders so
    join public.orders o on o.id = so.order_id
    cross join lateral (
      select case
        when public.mivo_fulfilment_rank(so.status::text) >= public.mivo_fulfilment_rank(o.status::text) then so.status::text
        else o.status::text end as status
    ) greatest_status
    left join lateral (
      select courier_name, tracking_number from public.shipments s
       where s.seller_order_id = so.id order by s.created_at limit 1
    ) sh on true
   where so.seller_id in (select public.my_shop_ids())
     and (p_seller_id is null or so.seller_id = p_seller_id)
   order by o.created_at desc
   limit 500;
$$;
grant execute on function public.seller_parcels(uuid) to authenticated;

commit;

