-- ---------------------------------------------------------------------
-- seller-rules.sql
-- ---------------------------------------------------------------------
-- =====================================================================
-- MIVO seller rules. Run after seller-onboarding.sql. Safe to re-run.
--
-- 1) One shop per account (like Shopee). MIVO admins are exempt, since
--    MIVO runs MIVO Direct.
-- 2) Approving an application copies what the seller already filled in
--    (pickup address, phone, email, legal name, SSM, address, bank) onto the
--    shop, so nobody has to type it again. Already-approved shops with
--    blanks are filled in now.
-- 3) Preferred Seller: a shop can apply; the superadmin approves or rejects.
-- =====================================================================

begin;

-- --------------------------------------------------- 1) one shop per account
create or replace function public.mivo_one_shop_per_owner()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.owner_id is not null
     and exists (select 1 from public.sellers s where s.owner_id = new.owner_id and s.id is distinct from new.id)
     and not exists (select 1 from public.platform_roles r where r.user_id = new.owner_id)
     and not coalesce((select p.role::text = 'admin' from public.profiles p where p.id = new.owner_id), false) then
    raise exception 'One MIVO account can have one shop. Manage your shop in Seller Centre.';
  end if;
  return new;
end;
$$;
drop trigger if exists sellers_one_per_owner on public.sellers;
create trigger sellers_one_per_owner before insert or update of owner_id on public.sellers
  for each row execute function public.mivo_one_shop_per_owner();
revoke all on function public.mivo_one_shop_per_owner() from public, anon, authenticated;

-- ------------------------------------- 2) application details onto the shop
create or replace function public.mivo_application_to_shop(p_application_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare
  a public.seller_applications%rowtype;
  m record;
begin
  select * into a from public.seller_applications where id = p_application_id;
  if not found then return; end if;

  -- column on sellers → value from the application. Only blank columns are filled.
  for m in
    select * from (values
      ('pickup_address',       to_jsonb(a.pickup_address)),
      ('phone',                to_jsonb(a.phone)),
      ('contact_phone',        to_jsonb(a.phone)),
      ('email',                to_jsonb(a.email)),
      ('contact_email',        to_jsonb(a.email)),
      ('legal_name',           to_jsonb(a.legal_name)),
      ('company_name',         to_jsonb(a.legal_name)),
      ('business_name',        to_jsonb(a.legal_name)),
      ('registration_number',  to_jsonb(coalesce(a.business_reg_no, a.ic_number))),
      ('business_reg_no',      to_jsonb(a.business_reg_no)),
      ('ssm_no',               to_jsonb(a.business_reg_no)),
      ('address',              to_jsonb(a.business_address)),
      ('business_address',     to_jsonb(a.business_address)),
      ('bank_name',            to_jsonb(a.bank_name)),
      ('bank_account_name',    to_jsonb(a.bank_account_name)),
      ('bank_account_number',  to_jsonb(a.bank_account_no)),
      ('bank_account_no',      to_jsonb(a.bank_account_no)),
      ('tin',                  to_jsonb(a.tin)),
      ('sst_no',               to_jsonb(a.sst_no))
    ) v(col, val)
  loop
    if m.val is null or m.val = 'null'::jsonb then continue; end if;
    if not exists (select 1 from information_schema.columns
                    where table_schema = 'public' and table_name = 'sellers' and column_name = m.col) then
      continue;
    end if;
    begin
      execute format(
        'update public.sellers s
            set %1$I = (jsonb_populate_record(null::public.sellers, jsonb_build_object(%2$L, $1))).%1$I
          where s.id = $2
            and (s.%1$I is null or btrim(s.%1$I::text) in ('''', ''{}'', ''""''))',
        m.col, m.col)
      using m.val, a.seller_id;
    exception when others then
      null; -- a column with an unexpected type: leave it for MIVO to fill.
    end;
  end loop;
end;
$$;
revoke all on function public.mivo_application_to_shop(uuid) from public, anon, authenticated;

create or replace function public.mivo_application_approved()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.status::text = 'approved' and old.status::text is distinct from 'approved' then
    perform public.mivo_application_to_shop(new.id);
  end if;
  return new;
end;
$$;
drop trigger if exists seller_applications_to_shop on public.seller_applications;
create trigger seller_applications_to_shop after update of status on public.seller_applications
  for each row execute function public.mivo_application_approved();
revoke all on function public.mivo_application_approved() from public, anon, authenticated;

-- Fill shops approved before this file existed.
do $$
declare a record;
begin
  for a in select id from public.seller_applications where status::text = 'approved' loop
    perform public.mivo_application_to_shop(a.id);
  end loop;
end;
$$;

-- --------------------------------------------------- 3) Preferred Seller
create table if not exists public.seller_tier_requests (
  id uuid primary key default gen_random_uuid(),
  seller_id uuid not null references public.sellers(id) on delete cascade,
  requested_tier text not null default 'preferred' check (requested_tier in ('preferred')),
  status text not null default 'pending' check (status in ('pending', 'approved', 'rejected')),
  seller_note text,
  admin_note text,
  requested_by uuid references auth.users(id) on delete set null,
  reviewed_by uuid references auth.users(id) on delete set null,
  reviewed_at timestamptz,
  created_at timestamptz not null default now()
);
create unique index if not exists seller_tier_requests_one_pending
  on public.seller_tier_requests (seller_id) where status = 'pending';
alter table public.seller_tier_requests enable row level security;
revoke all on public.seller_tier_requests from anon, authenticated;

-- Numbers MIVO looks at (also shown to the seller).
create or replace function public.mivo_shop_scorecard(p_seller_id uuid)
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'tier', (select tier from public.sellers where id = p_seller_id),
    'open_since', (select coalesce(approved_at, created_at) from public.sellers where id = p_seller_id),
    'orders_completed', (select count(*) from public.seller_orders so
                          where so.seller_id = p_seller_id and so.status::text in ('delivered', 'completed')),
    'orders_cancelled', (select count(*) from public.seller_orders so
                          where so.seller_id = p_seller_id and so.status::text in ('cancelled', 'refunded')),
    'orders_total', (select count(*) from public.seller_orders so join public.orders o on o.id = so.order_id
                      where so.seller_id = p_seller_id and o.payment_status::text in ('paid', 'partially_refunded', 'refunded')),
    'rating', (select round(avg(r.rating)::numeric, 2) from public.product_reviews r join public.products p on p.id = r.product_id
                where p.seller_id = p_seller_id),
    'reviews', (select count(*) from public.product_reviews r join public.products p on p.id = r.product_id
                 where p.seller_id = p_seller_id),
    'products', (select count(*) from public.products p where p.seller_id = p_seller_id and p.status::text = 'active'),
    'returns', (select count(*) from public.return_requests rr where rr.seller_id = p_seller_id)
  );
$$;

create or replace function public.seller_tier_status(p_seller_id uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  if not exists (select 1 from public.sellers where id = p_seller_id and owner_id = auth.uid()) and not public.is_admin() then
    raise exception 'Not your shop';
  end if;
  return public.mivo_shop_scorecard(p_seller_id) || jsonb_build_object(
    'request', (select to_jsonb(r) - 'requested_by' - 'reviewed_by'
                  from public.seller_tier_requests r where r.seller_id = p_seller_id
                 order by r.created_at desc limit 1));
end;
$$;

create or replace function public.seller_request_preferred(p_seller_id uuid, p_note text)
returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid; v_tier text;
begin
  select tier into v_tier from public.sellers where id = p_seller_id and owner_id = auth.uid() and status = 'approved';
  if not found then raise exception 'Not your shop'; end if;
  if v_tier in ('preferred', 'direct') then raise exception 'Your shop is already %', v_tier; end if;
  if exists (select 1 from public.seller_tier_requests where seller_id = p_seller_id and status = 'pending') then
    raise exception 'Your application is already with MIVO';
  end if;
  if exists (select 1 from public.seller_tier_requests where seller_id = p_seller_id and status = 'rejected'
              and reviewed_at > now() - interval '14 days') then
    raise exception 'You can apply again 14 days after the last decision';
  end if;
  insert into public.seller_tier_requests (seller_id, seller_note, requested_by)
  values (p_seller_id, nullif(btrim(coalesce(p_note, '')), ''), auth.uid())
  returning id into v_id;
  return v_id;
end;
$$;

-- Superadmin: requests with each shop's numbers.
create or replace function public.platform_tier_requests()
returns table (id uuid, seller_id uuid, shop_name text, slug text, status text, seller_note text, admin_note text,
               created_at timestamptz, reviewed_at timestamptz, scorecard jsonb)
language plpgsql stable security definer set search_path = public as $$
begin
  perform public.mivo_require_superadmin();
  return query
  select r.id, r.seller_id, s.shop_name, s.slug, r.status, r.seller_note, r.admin_note, r.created_at, r.reviewed_at,
         public.mivo_shop_scorecard(r.seller_id)
    from public.seller_tier_requests r join public.sellers s on s.id = r.seller_id
   order by (r.status = 'pending') desc, r.created_at desc
   limit 200;
end;
$$;

create or replace function public.platform_review_tier_request(p_id uuid, p_approve boolean, p_note text)
returns void language plpgsql security definer set search_path = public as $$
declare r public.seller_tier_requests%rowtype;
begin
  perform public.mivo_require_superadmin();
  select * into r from public.seller_tier_requests where id = p_id for update;
  if not found then raise exception 'Request not found'; end if;
  if r.status <> 'pending' then raise exception 'Already %', r.status; end if;
  if not p_approve and coalesce(btrim(p_note), '') = '' then raise exception 'Tell the seller why (they will see it)'; end if;

  update public.seller_tier_requests
     set status = case when p_approve then 'approved' else 'rejected' end,
         admin_note = nullif(btrim(coalesce(p_note, '')), ''), reviewed_by = auth.uid(), reviewed_at = now()
   where id = r.id;

  if p_approve then
    update public.sellers set tier = 'preferred', updated_at = now() where id = r.seller_id;
  end if;

  perform public.platform_send_notice(
    case when p_approve then 'You are now a Preferred Seller' else 'Preferred Seller application' end,
    case when p_approve
      then 'Congratulations! Your shop now shows the Preferred badge to buyers.' || coalesce(E'\n\n' || nullif(btrim(coalesce(p_note, '')), ''), '')
      else 'MIVO couldn''t approve your application this time: ' || btrim(p_note)
    end,
    array[r.seller_id], 'info', null);
end;
$$;

-- Superadmin: set a shop's tier directly (e.g. take Preferred away).
create or replace function public.platform_set_shop_tier(p_seller_id uuid, p_tier text)
returns void language plpgsql security definer set search_path = public as $$
begin
  perform public.mivo_require_superadmin();
  if p_tier not in ('preferred', 'standard') then raise exception 'Choose Preferred or Standard'; end if;
  update public.sellers set tier = p_tier, updated_at = now() where id = p_seller_id and tier <> 'direct';
  if not found then raise exception 'Shop not found (MIVO Direct can''t be changed)'; end if;
end;
$$;

revoke all on function public.mivo_shop_scorecard(uuid) from public, anon, authenticated;
revoke all on function public.seller_tier_status(uuid) from public, anon;
revoke all on function public.seller_request_preferred(uuid, text) from public, anon;
revoke all on function public.platform_tier_requests() from public, anon;
revoke all on function public.platform_review_tier_request(uuid, boolean, text) from public, anon;
revoke all on function public.platform_set_shop_tier(uuid, text) from public, anon;
grant execute on function public.seller_tier_status(uuid) to authenticated;
grant execute on function public.seller_request_preferred(uuid, text) to authenticated;
grant execute on function public.platform_tier_requests() to authenticated;
grant execute on function public.platform_review_tier_request(uuid, boolean, text) to authenticated;
grant execute on function public.platform_set_shop_tier(uuid, text) to authenticated;

commit;

notify pgrst, 'reload schema';


-- ---------------------------------------------------------------------
-- commission-now.sql
-- ---------------------------------------------------------------------
-- =====================================================================
-- MIVO commission: change a shop's rate right away (any shop, including
-- MIVO Direct or your own shops). Run after platform.sql. Safe to re-run.
-- Scheduled changes still work as before; this is the "set it now" button.
-- =====================================================================

begin;

create or replace function public.platform_set_shop_commission(p_seller_id uuid, p_rate numeric, p_notify boolean default true)
returns void language plpgsql security definer set search_path = public as $$
declare s public.sellers%rowtype;
begin
  perform public.mivo_require_superadmin();
  if p_rate is null or p_rate < 0 or p_rate > 50 then raise exception 'Commission must be between 0%% and 50%%'; end if;
  select * into s from public.sellers where id = p_seller_id for update;
  if not found then raise exception 'Shop not found'; end if;

  update public.sellers set commission_rate = round(p_rate, 2), updated_at = now() where id = p_seller_id;

  -- Keep a record next to the scheduled changes.
  insert into public.commission_changes (seller_ids, rate, starts_at, ends_at, reason, status, previous_rates, created_by)
  values (array[p_seller_id], round(p_rate, 2), now(), null, 'Set now by MIVO', 'done',
          jsonb_build_object(p_seller_id::text, s.commission_rate), auth.uid());

  if coalesce(p_notify, true) and coalesce(s.tier, 'standard') <> 'direct' and s.owner_id is distinct from auth.uid() then
    perform public.platform_send_notice('Commission change: ' || round(p_rate, 2) || '%',
      'MIVO commission for your shop is now ' || round(p_rate, 2) || '% (was ' || coalesce(s.commission_rate, 0) || '%).',
      array[p_seller_id], 'commission_change', null);
  end if;
end;
$$;
revoke all on function public.platform_set_shop_commission(uuid, numeric, boolean) from public, anon;
grant execute on function public.platform_set_shop_commission(uuid, numeric, boolean) to authenticated;

commit;

notify pgrst, 'reload schema';


-- ---------------------------------------------------------------------
-- combined-shipping.sql
-- ---------------------------------------------------------------------
-- =====================================================================
-- MIVO: one parcel, one shipping fee for shops that ship from the same place.
-- Run after checkout-per-shop.sql and easyparcel.sql. Safe to re-run.
--
-- Shops of the same owner with the same pickup address form a "shipping
-- group". At checkout the group is priced as one parcel (combined weight),
-- the fee is charged once, and when one of its parcels ships, the others in
-- the same order ship with it under the same courier and tracking number.
-- =====================================================================

begin;

alter table public.seller_orders add column if not exists shipping_group text;

-- Same owner + same pickup address (spaces/case ignored) = one group.
create or replace function public.mivo_pickup_group(p_seller_id uuid)
returns text language sql stable security definer set search_path = public as $$
  select case
    when coalesce(s.pickup_address ->> 'postcode', '') = '' or coalesce(s.pickup_address ->> 'line', '') = ''
      then 'shop:' || s.id::text
    else coalesce(s.owner_id::text, 'none') || '|' || (s.pickup_address ->> 'postcode') || '|'
         || lower(regexp_replace(s.pickup_address ->> 'line', '[^a-zA-Z0-9]', '', 'g'))
  end
  from public.sellers s where s.id = p_seller_id;
$$;
revoke all on function public.mivo_pickup_group(uuid) from public, anon;
grant execute on function public.mivo_pickup_group(uuid) to authenticated, service_role;

-- Shipping options per parcel (a parcel = shops shipping from the same place).
create or replace function public.quote_shipping_by_shop(p_items jsonb, p_state text, p_postcode text)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_group record;
  v_out jsonb := '[]'::jsonb;
begin
  for v_group in
    with lines as (
      select v.id as variant_id, (i ->> 'quantity')::int as quantity, v.seller_id, s.shop_name, s.tier,
             public.mivo_pickup_group(v.seller_id) as grp
        from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) i
        join public.product_variants v on v.id = (i ->> 'variant_id')::uuid
        join public.sellers s on s.id = v.seller_id
    ), shops as (
      select distinct seller_id, shop_name, tier, grp from lines
    )
    select l.grp,
           (array_agg(sh.seller_id order by (sh.tier = 'direct') desc, sh.shop_name))[1] as lead_id,
           (select jsonb_agg(x.seller_id order by (x.tier = 'direct') desc, x.shop_name) from shops x where x.grp = l.grp) as seller_ids,
           (select string_agg(x.shop_name, ' · ' order by (x.tier = 'direct') desc, x.shop_name) from shops x where x.grp = l.grp) as names,
           (array_agg(sh.tier order by (sh.tier = 'direct') desc, sh.shop_name))[1] as tier,
           jsonb_agg(jsonb_build_object('variant_id', l.variant_id, 'quantity', l.quantity)) as items
      from lines l join shops sh on sh.seller_id = l.seller_id
     group by l.grp
     order by bool_or(sh.tier = 'direct') desc, min(sh.shop_name)
  loop
    v_out := v_out || jsonb_build_array(jsonb_build_object(
      'seller_id', v_group.lead_id,
      'seller_ids', v_group.seller_ids,
      'group', v_group.grp,
      'shop_name', v_group.names,
      'tier', v_group.tier,
      'options', public.mivo_quote_options(v_group.items, p_state, p_postcode)
    ));
  end loop;
  return v_out;
end;
$$;
grant execute on function public.quote_shipping_by_shop(jsonb, text, text) to anon, authenticated;

create or replace function public.create_pending_order_by_shop(
  p_items jsonb,
  p_shipping_address jsonb,
  p_customer_note text default null,
  p_voucher_id uuid default null,
  p_couriers jsonb default '{}'::jsonb,
  p_quote_id uuid default null
)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_quotes jsonb;
  v_shop jsonb;
  v_choice jsonb;
  v_code text;
  v_first_code text;
  v_shipping numeric := 0;
  v_result jsonb;
  v_order public.orders%rowtype;
  v_discount numeric;
  v_voucher record;
  v_live public.checkout_shipping_quotes%rowtype;
  v_fees jsonb := '[]'::jsonb;   -- [{seller_id, fee, courier_code, courier_name}]
  v_promo public.shipping_promotions%rowtype;
  v_subsidy numeric := 0;
begin
  if auth.uid() is null then raise exception 'Please sign in'; end if;

  v_quotes := public.quote_shipping_by_shop(p_items, p_shipping_address ->> 'state', p_shipping_address ->> 'postcode');
  if jsonb_array_length(v_quotes) = 0 then raise exception 'Your cart is empty'; end if;

  if p_quote_id is not null then
    -- Live EasyParcel prices quoted for this cart and address.
    select * into v_live from public.checkout_shipping_quotes
     where id = p_quote_id and user_id = auth.uid();
    if not found or v_live.expires_at < now() then
      raise exception 'Shipping price expired. Please refresh the checkout page.';
    end if;
    if v_live.items_key <> public.mivo_items_key(p_items)
       or v_live.postcode <> coalesce(p_shipping_address ->> 'postcode', '')
       or v_live.state <> coalesce(p_shipping_address ->> 'state', '') then
      raise exception 'Your cart or address changed. Please refresh the checkout page.';
    end if;
    for v_shop in select * from jsonb_array_elements(v_quotes) loop
      select q into v_choice from jsonb_array_elements(v_live.shops) q
       where q ->> 'seller_id' = v_shop ->> 'seller_id'
          or coalesce(q -> 'seller_ids', '[]'::jsonb) ? (v_shop ->> 'seller_id')
       limit 1;
      if v_choice is null then raise exception 'Shipping price missing for %', v_shop ->> 'shop_name'; end if;
      v_shipping := v_shipping + coalesce((v_choice ->> 'amount')::numeric, 0);
      v_fees := v_fees || jsonb_build_array(jsonb_build_object(
        'seller_id', v_shop ->> 'seller_id', 'seller_ids', coalesce(v_shop -> 'seller_ids', jsonb_build_array(v_shop ->> 'seller_id')),
        'group', v_shop ->> 'group', 'fee', (v_choice ->> 'amount')::numeric,
        'courier_code', v_choice ->> 'service_id', 'courier_name', v_choice ->> 'courier'));
      -- create_pending_order still needs one of MIVO's courier codes.
      v_first_code := coalesce(v_first_code, v_shop -> 'options' -> 0 ->> 'courier_code');
      v_choice := null;
    end loop;
  else
    -- MIVO's own shipping rules: one courier per shop.
    for v_shop in select * from jsonb_array_elements(v_quotes) loop
      v_code := p_couriers ->> (v_shop ->> 'seller_id');
      v_choice := null;
      select o into v_choice from jsonb_array_elements(v_shop -> 'options') o
       where o ->> 'courier_code' = v_code limit 1;
      if v_choice is null then
        raise exception 'Choose a courier for %', v_shop ->> 'shop_name';
      end if;
      v_first_code := coalesce(v_first_code, v_code);
      v_shipping := v_shipping + coalesce((v_choice ->> 'shipping_amount')::numeric, 0);
      v_fees := v_fees || jsonb_build_array(jsonb_build_object(
        'seller_id', v_shop ->> 'seller_id', 'seller_ids', coalesce(v_shop -> 'seller_ids', jsonb_build_array(v_shop ->> 'seller_id')),
        'group', v_shop ->> 'group', 'fee', (v_choice ->> 'shipping_amount')::numeric,
        'courier_code', v_code, 'courier_name', v_choice ->> 'courier_name'));
    end loop;
  end if;

  -- The existing checkout does stock, prices, vouchers and the order itself.
  v_result := public.create_pending_order(
    p_items,
    p_shipping_address || jsonb_build_object('courier_code', v_first_code, 'shop_couriers', p_couriers),
    p_customer_note,
    p_voucher_id
  );

  select * into v_order from public.orders
   where order_number = v_result ->> 'order_number' and user_id = auth.uid()
   for update;
  if not found then raise exception 'Order not found after checkout'; end if;

  -- MIVO free-shipping promotion: MIVO pays shipping (up to the cap) when the
  -- order reaches the minimum spend. The buyer pays only what's left.
  select * into v_promo from public.shipping_promotions
   where active and now() between starts_at and ends_at
   order by max_subsidy desc nulls first, min_spend limit 1;
  if found and coalesce(v_order.subtotal, 0) >= v_promo.min_spend then
    v_subsidy := least(v_shipping, coalesce(v_promo.max_subsidy, v_shipping));
  end if;
  v_shipping := v_shipping - v_subsidy;

  -- Free-shipping vouchers follow the new shipping total.
  v_discount := coalesce(v_order.discount_amount, 0);
  if v_order.voucher_code is not null then
    select discount_type, max_discount into v_voucher
      from public.vouchers where code = v_order.voucher_code limit 1;
    if found and v_voucher.discount_type = 'free_shipping' then
      v_discount := least(v_shipping, coalesce(nullif(v_voucher.max_discount, 0), v_shipping));
    end if;
  end if;

  update public.orders
     set shipping_amount = v_shipping,
         shipping_subsidy = v_subsidy,
         shipping_promotion_id = case when v_subsidy > 0 then v_promo.id end,
         discount_amount = v_discount,
         total_amount = greatest(0, coalesce(subtotal, 0) + v_shipping - v_discount),
         updated_at = now()
   where id = v_order.id;

  -- Shops that ship from the same address travel as one parcel: the fee sits
  -- on the first shop's parcel, the others are 0, and all share a group key
  -- so they ship together with one tracking number.
  for v_shop in select * from jsonb_array_elements(v_fees) loop
    update public.seller_orders
       set buyer_courier_code = v_shop ->> 'courier_code',
           buyer_courier_name = v_shop ->> 'courier_name',
           buyer_shipping_fee = case when seller_id = (v_shop ->> 'seller_id')::uuid then (v_shop ->> 'fee')::numeric else 0 end,
           shipping_group = case when jsonb_array_length(v_shop -> 'seller_ids') > 1 then v_shop ->> 'group' end
     where order_id = v_order.id
       and seller_id in (select (x)::uuid from jsonb_array_elements_text(v_shop -> 'seller_ids') x);
  end loop;

  if p_quote_id is not null then
    delete from public.checkout_shipping_quotes where id = p_quote_id or expires_at < now() - interval '1 day';
  end if;

  return v_result || jsonb_build_object(
    'shipping_amount', v_shipping,
    'shipping_subsidy', v_subsidy,
    'discount_amount', v_discount,
    'total_amount', greatest(0, coalesce(v_order.subtotal, 0) + v_shipping - v_discount)
  );
end;
$$;


revoke all on function public.create_pending_order_by_shop(jsonb, jsonb, text, uuid, jsonb, uuid) from public, anon;
grant execute on function public.create_pending_order_by_shop(jsonb, jsonb, text, uuid, jsonb, uuid) to authenticated;

-- When a parcel in a shipping group gets its tracking number, the other
-- parcels of that group in the same order ship with it.
create or replace function public.mivo_ship_group_together()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_so public.seller_orders%rowtype;
  v_sib record;
begin
  if coalesce(current_setting('mivo.group_ship', true), '') = 'on' then return new; end if;
  if coalesce(btrim(new.tracking_number), '') = '' then return new; end if;
  if tg_op = 'UPDATE' and old.tracking_number is not distinct from new.tracking_number then return new; end if;

  select * into v_so from public.seller_orders where id = new.seller_order_id;
  if not found or v_so.shipping_group is null then return new; end if;

  perform set_config('mivo.group_ship', 'on', true);
  for v_sib in
    select so.id from public.seller_orders so
     where so.order_id = v_so.order_id and so.shipping_group = v_so.shipping_group and so.id <> v_so.id
       and so.status::text not in ('shipped', 'delivered', 'completed', 'cancelled', 'refunded')
  loop
    begin
      perform public.admin_update_shop_fulfilment(v_sib.id, 'shipped', new.courier_name, new.tracking_number, new.tracking_url);
      update public.shipments s
         set provider = new.provider, awb_url = new.awb_url, label_urls = new.label_urls
       where s.seller_order_id = v_sib.id and s.tracking_number = new.tracking_number;
    exception when others then
      raise warning 'MIVO: could not ship parcel % with its group: %', v_sib.id, sqlerrm;
    end;
  end loop;
  perform set_config('mivo.group_ship', 'off', true);
  return new;
end;
$$;
revoke all on function public.mivo_ship_group_together() from public, anon, authenticated;
drop trigger if exists shipments_ship_group_together on public.shipments;
create trigger shipments_ship_group_together after insert or update of tracking_number on public.shipments
  for each row execute function public.mivo_ship_group_together();

commit;

notify pgrst, 'reload schema';


-- ---------------------------------------------------------------------
-- own-shops.sql
-- ---------------------------------------------------------------------
-- =====================================================================
-- MIVO's own shops. Run after seller-rules.sql. Safe to re-run.
--
--  * Shops the superadmin owns (other than MIVO Direct) are Preferred, and
--    their products' vehicle fitment counts as MIVO-verified.
--  * One pickup address can be applied to all of the superadmin's shops.
--  * Platform settings, starting with whether "Sell on MIVO" is shown.
-- =====================================================================

begin;

create or replace function public.mivo_is_superadmin_user(p_user uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.platform_roles r where r.user_id = p_user and r.role = 'superadmin');
$$;
revoke all on function public.mivo_is_superadmin_user(uuid) from public, anon, authenticated;

-- 1) Own shops are Preferred (MIVO Direct stays Direct).
update public.sellers set tier = 'preferred', updated_at = now()
 where public.mivo_is_superadmin_user(owner_id) and coalesce(tier, 'standard') = 'standard';

create or replace function public.mivo_own_shop_tier()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if public.mivo_is_superadmin_user(new.owner_id) and coalesce(new.tier, 'standard') = 'standard' then
    new.tier := 'preferred';
  end if;
  return new;
end;
$$;
drop trigger if exists sellers_own_shop_tier on public.sellers;
create trigger sellers_own_shop_tier before insert or update of owner_id on public.sellers
  for each row execute function public.mivo_own_shop_tier();
revoke all on function public.mivo_own_shop_tier() from public, anon, authenticated;

-- ...and their fitment is trusted like MIVO Direct's.
do $$
begin
  if exists (select 1 from information_schema.columns
              where table_schema = 'public' and table_name = 'products' and column_name = 'fitment_verified') then
    update public.products p set fitment_verified = true
      from public.sellers s
     where s.id = p.seller_id and public.mivo_is_superadmin_user(s.owner_id) and not coalesce(p.fitment_verified, false);

    create or replace function public.mivo_own_shop_fitment()
    returns trigger language plpgsql security definer set search_path = public as $f$
    begin
      if exists (select 1 from public.sellers s where s.id = new.seller_id and public.mivo_is_superadmin_user(s.owner_id)) then
        new.fitment_verified := true;
      end if;
      return new;
    end;
    $f$;
    revoke all on function public.mivo_own_shop_fitment() from public, anon, authenticated;
    -- Named to run after products_guard_verification (triggers fire in name order).
    drop trigger if exists products_zz_own_shop_fitment on public.products;
    create trigger products_zz_own_shop_fitment before insert or update of seller_id on public.products
      for each row execute function public.mivo_own_shop_fitment();
  else
    raise notice 'Run fitment-verification.sql first, then this file again, to trust fitment on your own shops.';
  end if;
end;
$$;

-- 2) One pickup address for all my shops.
create or replace function public.platform_apply_pickup_to_my_shops(p_address jsonb)
returns integer language plpgsql security definer set search_path = public as $$
declare n integer;
begin
  perform public.mivo_require_superadmin();
  if coalesce(btrim(p_address ->> 'name'), '') = '' or coalesce(btrim(p_address ->> 'phone'), '') = ''
     or coalesce(btrim(p_address ->> 'line'), '') = '' or coalesce(p_address ->> 'postcode', '') !~ '^\d{5}$'
     or coalesce(btrim(p_address ->> 'city'), '') = '' or coalesce(btrim(p_address ->> 'state'), '') = '' then
    raise exception 'Fill in name, phone, street, 5-digit postcode, city and state';
  end if;
  update public.sellers set pickup_address = p_address, updated_at = now() where owner_id = auth.uid();
  get diagnostics n = row_count;
  return n;
end;
$$;
revoke all on function public.platform_apply_pickup_to_my_shops(jsonb) from public, anon;
grant execute on function public.platform_apply_pickup_to_my_shops(jsonb) to authenticated;

-- 3) Platform settings (public read, superadmin write).
create table if not exists public.platform_settings (
  key text primary key,
  value jsonb not null,
  updated_at timestamptz not null default now(),
  updated_by uuid references auth.users(id) on delete set null
);
alter table public.platform_settings enable row level security;
revoke all on public.platform_settings from anon, authenticated;
grant select on public.platform_settings to anon, authenticated;
drop policy if exists "platform settings: everyone reads" on public.platform_settings;
create policy "platform settings: everyone reads" on public.platform_settings for select to anon, authenticated using (true);
insert into public.platform_settings (key, value) values ('show_sell_link', 'false'::jsonb) on conflict (key) do nothing;

create or replace function public.platform_set_setting(p_key text, p_value jsonb)
returns void language plpgsql security definer set search_path = public as $$
begin
  perform public.mivo_require_superadmin();
  if p_key not in ('show_sell_link') then raise exception 'Unknown setting'; end if;
  insert into public.platform_settings (key, value, updated_at, updated_by) values (p_key, p_value, now(), auth.uid())
  on conflict (key) do update set value = excluded.value, updated_at = now(), updated_by = auth.uid();
end;
$$;
revoke all on function public.platform_set_setting(text, jsonb) from public, anon;
grant execute on function public.platform_set_setting(text, jsonb) to authenticated;

commit;

notify pgrst, 'reload schema';


-- ---------------------------------------------------------------------
-- sku-repeat.sql
-- ---------------------------------------------------------------------
-- =====================================================================
-- MIVO: the same SKU may be listed more than once, in one shop or several.
-- Run once in Supabase → SQL Editor. Safe to re-run.
--
-- Shopee shops often list one part in several listings (and several
-- shops). MIVO keeps their SKUs exactly as in Shopee; variants with the same
-- SKU share one stock (stock_group, see multi-shop-linked-stock.sql).
-- This removes the "one SKU per shop" rule if a database has it.
-- =====================================================================

begin;

drop index if exists public.product_variants_seller_sku_unique_idx;
create index if not exists product_variants_seller_sku_idx
  on public.product_variants (seller_id, upper(btrim(sku)));

commit;

notify pgrst, 'reload schema';


-- ---------------------------------------------------------------------
-- customer-emails.sql
-- ---------------------------------------------------------------------
-- =====================================================================
-- MIVO customer emails. Safe to re-run.
--
-- 1) email_queue: every email MIVO sends (receipt, shipped, delivered,
--    cancelled, refunded, promotions) goes through this table once.
-- 2) Triggers add to the queue when an order is paid / cancelled / refunded
--    and when a parcel ships or is delivered. They never block the order.
-- 3) Promotions: customers choose to receive them (profiles.marketing_opt_in),
--    every promotion has an unsubscribe link.
-- 4) Optional instant sending: after setting Vercel env EMAIL_QUEUE_SECRET, run
--      select public.mivo_email_setup('https://mivo-v2.vercel.app', '<same secret>');
--    Without it, emails still go out from the website itself and the daily check.
-- =====================================================================

begin;

-- --------------------------------------------------------------- 1) queue
create table if not exists public.email_queue (
  id uuid primary key default gen_random_uuid(),
  kind text not null check (kind in ('order_paid', 'order_cancelled', 'order_refunded',
                                     'parcel_shipped', 'parcel_delivered', 'campaign')),
  ref text not null,                       -- what makes it unique, e.g. the order id
  order_id uuid,
  seller_order_id uuid,
  campaign_id uuid,
  user_id uuid,
  recipient text,                          -- filled in when it is sent
  status text not null default 'pending' check (status in ('pending', 'sending', 'sent', 'failed', 'skipped')),
  attempts integer not null default 0,
  last_error text,
  created_at timestamptz not null default now(),
  sent_at timestamptz
);
create unique index if not exists email_queue_kind_ref on public.email_queue (kind, ref);
create index if not exists email_queue_pending on public.email_queue (status, created_at) where status in ('pending', 'sending');
alter table public.email_queue enable row level security;
revoke all on public.email_queue from anon, authenticated;
drop policy if exists "email_queue: admin read" on public.email_queue;
create policy "email_queue: admin read" on public.email_queue for select to authenticated using (public.is_admin());
grant select on public.email_queue to authenticated;

-- Instant sending (pg_net). One row; only the database can read it.
create table if not exists public.mivo_email_settings (
  id boolean primary key default true check (id),
  process_url text not null,
  secret text not null,
  updated_at timestamptz not null default now()
);
alter table public.mivo_email_settings enable row level security;
revoke all on public.mivo_email_settings from anon, authenticated;

create or replace function public.mivo_email_setup(p_site_url text, p_secret text)
returns text language plpgsql security definer set search_path = public as $$
begin
  if coalesce(btrim(p_secret), '') = '' or length(p_secret) < 16 then
    raise exception 'Use a secret of at least 16 characters (the same as EMAIL_QUEUE_SECRET in Vercel)';
  end if;
  begin
    create extension if not exists pg_net;
  exception when others then
    return 'Saved, but pg_net could not be enabled here: turn it on in Database > Extensions';
  end;
  insert into public.mivo_email_settings (id, process_url, secret)
  values (true, rtrim(p_site_url, '/') || '/api/email/process', p_secret)
  on conflict (id) do update set process_url = excluded.process_url, secret = excluded.secret, updated_at = now();
  return 'OK: emails will be sent right away';
end;
$$;
revoke all on function public.mivo_email_setup(text, text) from public, anon, authenticated;

-- Ask the website to send what is waiting. Never raises.
create or replace function public.mivo_email_kick()
returns void language plpgsql security definer set search_path = public as $$
declare s public.mivo_email_settings%rowtype;
begin
  select * into s from public.mivo_email_settings where id;
  if not found or to_regnamespace('net') is null then return; end if;
  execute 'select net.http_post(url := $1, body := ''{}''::jsonb, headers := $2)'
    using s.process_url, jsonb_build_object('Content-Type', 'application/json', 'x-mivo-email-secret', s.secret);
exception when others then
  null;
end;
$$;
revoke all on function public.mivo_email_kick() from public, anon, authenticated;

create or replace function public.mivo_email_enqueue(p_kind text, p_ref text, p_order uuid, p_seller_order uuid, p_user uuid)
returns void language plpgsql security definer set search_path = public as $$
begin
  if p_user is null then return; end if;
  insert into public.email_queue (kind, ref, order_id, seller_order_id, user_id)
  values (p_kind, p_ref, p_order, p_seller_order, p_user)
  on conflict (kind, ref) do nothing;
  if found then perform public.mivo_email_kick(); end if;
exception when others then
  null; -- an email problem must never stop an order from saving
end;
$$;
revoke all on function public.mivo_email_enqueue(text, text, uuid, uuid, uuid) from public, anon, authenticated;

-- Website: take a batch to send (two senders never get the same email).
-- p_campaigns = false while the day's sending limit is used up: order emails still go.
drop function if exists public.mivo_email_claim(integer);
create or replace function public.mivo_email_claim(p_limit integer, p_campaigns boolean default true)
returns setof public.email_queue language sql security definer set search_path = public as $$
  update public.email_queue q
     set status = 'sending', attempts = q.attempts + 1
   where q.id in (
     select id from public.email_queue
      where (status = 'pending' or (status = 'sending' and created_at < now() - interval '15 minutes' and attempts < 5)
             or (status = 'failed' and attempts < 3 and created_at > now() - interval '3 days'))
        and (p_campaigns or kind <> 'campaign')
      order by (kind = 'campaign'), created_at
      limit greatest(1, least(coalesce(p_limit, 20), 100))
      for update skip locked)
  returning q.*;
$$;
revoke all on function public.mivo_email_claim(integer, boolean) from public, anon, authenticated;

-- --------------------------------------------------------------- 2) triggers
create or replace function public.mivo_order_emails()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  n jsonb := to_jsonb(new);
  o jsonb := to_jsonb(old);
  uid uuid := nullif(n ->> 'user_id', '')::uuid;
begin
  if n ->> 'payment_status' = 'paid' and o ->> 'payment_status' is distinct from 'paid' then
    perform public.mivo_email_enqueue('order_paid', new.id::text, new.id, null, uid);
  end if;
  if n ->> 'status' = 'cancelled' and o ->> 'status' is distinct from 'cancelled'
     and coalesce(n ->> 'paid_at', o ->> 'paid_at') is not null then
    perform public.mivo_email_enqueue('order_cancelled', new.id::text, new.id, null, uid);
  end if;
  if n ->> 'payment_status' in ('refunded', 'partially_refunded')
     and o ->> 'payment_status' is distinct from n ->> 'payment_status' then
    perform public.mivo_email_enqueue('order_refunded', new.id::text || ':' || (n ->> 'payment_status'), new.id, null, uid);
  end if;
  return new;
exception when others then
  return new;
end;
$$;
drop trigger if exists orders_customer_emails on public.orders;
create trigger orders_customer_emails after update on public.orders
  for each row execute function public.mivo_order_emails();
revoke all on function public.mivo_order_emails() from public, anon, authenticated;

create or replace function public.mivo_parcel_emails()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  n jsonb := to_jsonb(new);
  o jsonb := to_jsonb(old);
  uid uuid;
begin
  if n ->> 'status' in ('shipped', 'delivered') and o ->> 'status' is distinct from n ->> 'status' then
    select user_id into uid from public.orders where id = new.order_id;
    perform public.mivo_email_enqueue(
      case when n ->> 'status' = 'shipped' then 'parcel_shipped' else 'parcel_delivered' end,
      new.id::text, new.order_id, new.id, coalesce(uid, nullif(n ->> 'customer_id', '')::uuid));
  end if;
  return new;
exception when others then
  return new;
end;
$$;
drop trigger if exists seller_orders_customer_emails on public.seller_orders;
create trigger seller_orders_customer_emails after update on public.seller_orders
  for each row execute function public.mivo_parcel_emails();
revoke all on function public.mivo_parcel_emails() from public, anon, authenticated;

-- --------------------------------------------------------------- 3) promotions
alter table public.profiles add column if not exists marketing_opt_in boolean not null default false;
alter table public.profiles add column if not exists marketing_opt_in_at timestamptz;

-- A customer turns promotions on or off for themselves.
create or replace function public.set_marketing_opt_in(p_on boolean)
returns boolean language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then raise exception 'Please sign in'; end if;
  update public.profiles
     set marketing_opt_in = coalesce(p_on, false),
         marketing_opt_in_at = now()
   where id = auth.uid();
  return coalesce(p_on, false);
end;
$$;
-- {"on": true/false, "decided": has the customer ever chosen}
drop function if exists public.my_marketing_opt_in();
create or replace function public.my_marketing_opt_in()
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object('on', coalesce(p.marketing_opt_in, false), 'decided', p.marketing_opt_in_at is not null)
    from public.profiles p where p.id = auth.uid();
$$;
revoke all on function public.set_marketing_opt_in(boolean) from public, anon;
revoke all on function public.my_marketing_opt_in() from public, anon;
grant execute on function public.set_marketing_opt_in(boolean) to authenticated;
grant execute on function public.my_marketing_opt_in() to authenticated;

create table if not exists public.email_campaigns (
  id uuid primary key default gen_random_uuid(),
  subject text not null,
  headline text,
  body text not null,
  image_url text,
  button_text text,
  button_url text,
  status text not null default 'sending' check (status in ('sending', 'sent')),
  recipients integer not null default 0,
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now()
);
alter table public.email_campaigns enable row level security;
revoke all on public.email_campaigns from anon, authenticated;
drop policy if exists "email_campaigns: admin read" on public.email_campaigns;
create policy "email_campaigns: admin read" on public.email_campaigns for select to authenticated using (public.is_admin());
grant select on public.email_campaigns to authenticated;

-- Website (after checking the admin): put one email per subscribed customer in the queue.
create or replace function public.mivo_queue_campaign(p_campaign uuid)
returns integer language plpgsql security definer set search_path = public as $$
declare v_count integer;
begin
  insert into public.email_queue (kind, ref, campaign_id, user_id)
  select 'campaign', p_campaign::text || ':' || p.id::text, p_campaign, p.id
    from public.profiles p
   where p.marketing_opt_in and coalesce(btrim(p.email), '') <> ''
  on conflict (kind, ref) do nothing;
  get diagnostics v_count = row_count;
  update public.email_campaigns set recipients = recipients + v_count where id = p_campaign;
  perform public.mivo_email_kick();
  return v_count;
end;
$$;
revoke all on function public.mivo_queue_campaign(uuid) from public, anon, authenticated;

commit;

notify pgrst, 'reload schema';


-- ---------------------------------------------------------------------
-- shopee-sync.sql
-- ---------------------------------------------------------------------
-- =====================================================================
-- MIVO: keep products in step with Shopee. Safe to re-run.
--
-- 1) Each imported product / option remembers its Shopee Item ID and
--    Variation ID (external_ref, e.g. 'shopee:58169897867'), so importing
--    the same listing again updates it instead of adding a copy.
-- 2) mivo_sync_variants: the website updates price / original price / stock
--    of many options in one go (used by Import from Shopee).
-- =====================================================================

begin;

alter table public.products add column if not exists external_ref text;
alter table public.product_variants add column if not exists external_ref text;
create index if not exists products_seller_external_ref on public.products (seller_id, external_ref) where external_ref is not null;
create index if not exists product_variants_seller_external_ref on public.product_variants (seller_id, external_ref) where external_ref is not null;

-- p_rows: [{"id": "<variant uuid>", "price": 128, "compare_at_price": 400, "stock": 10, "external_ref": "shopee:123"}]
-- "stock" and "external_ref" are optional. Only options of p_shop are touched.
create or replace function public.mivo_sync_variants(p_shop uuid, p_rows jsonb)
returns integer language plpgsql security definer set search_path = public as $$
declare v_count integer;
begin
  update public.product_variants v
     set price = greatest(0, r.price),
         compare_at_price = case when r.compare_at_price is not null and r.compare_at_price > r.price then r.compare_at_price end,
         stock_on_hand = coalesce(greatest(0, r.stock), v.stock_on_hand),
         external_ref = coalesce(nullif(r.external_ref, ''), v.external_ref),
         updated_at = now()
    from jsonb_to_recordset(coalesce(p_rows, '[]'::jsonb))
         as r(id uuid, price numeric, compare_at_price numeric, stock integer, external_ref text)
   where v.id = r.id
     and v.seller_id = p_shop
     and r.price is not null;
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;
revoke all on function public.mivo_sync_variants(uuid, jsonb) from public, anon, authenticated;

commit;

notify pgrst, 'reload schema';


-- ---------------------------------------------------------------------
-- return-address-fallback.sql
-- ---------------------------------------------------------------------
-- =====================================================================
-- Returns: where the customer sends the item back. Safe to re-run.
-- Uses the shop's return address; when that is empty, the shop's pickup
-- address (usually the same warehouse), so the customer always sees one.
-- =====================================================================

begin;

create or replace function public.return_request_return_address(p_request_id uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v jsonb;
  s record;
  pickup jsonb;
  line text;
begin
  select sl.shop_name, sl.return_name, sl.return_phone, sl.return_address,
         to_jsonb(sl) -> 'pickup_address' as pickup_address, to_jsonb(sl) ->> 'phone' as shop_phone
    into s
    from public.return_requests r join public.sellers sl on sl.id = r.seller_id
   where r.id = p_request_id and r.customer_id = auth.uid()
     and r.status in ('approved_return', 'returning');
  if not found then return null; end if;

  if coalesce(btrim(s.return_address), '') <> '' then
    return jsonb_build_object('shop', s.shop_name, 'name', s.return_name, 'phone', s.return_phone, 'address', s.return_address);
  end if;

  pickup := case when jsonb_typeof(s.pickup_address) = 'object' then s.pickup_address else '{}'::jsonb end;
  line := concat_ws(', ',
    nullif(btrim(coalesce(pickup ->> 'line', pickup ->> 'address_line_1', pickup ->> 'address', '')), ''),
    nullif(btrim(coalesce(pickup ->> 'line2', pickup ->> 'address_line_2', '')), ''),
    nullif(btrim(concat_ws(' ', pickup ->> 'postcode', pickup ->> 'city')), ''),
    nullif(btrim(coalesce(pickup ->> 'state', '')), ''));
  if coalesce(line, '') = '' then
    return jsonb_build_object('shop', s.shop_name, 'name', s.return_name, 'phone', s.return_phone, 'address', null);
  end if;
  v := jsonb_build_object(
    'shop', s.shop_name,
    'name', coalesce(nullif(btrim(s.return_name), ''), pickup ->> 'name', s.shop_name),
    'phone', coalesce(nullif(btrim(s.return_phone), ''), pickup ->> 'phone', s.shop_phone),
    'address', line);
  return v;
end;
$$;
revoke all on function public.return_request_return_address(uuid) from public, anon;
grant execute on function public.return_request_return_address(uuid) to authenticated;

commit;

notify pgrst, 'reload schema';


-- ---------------------------------------------------------------------
-- return-shipping-share.sql
-- ---------------------------------------------------------------------
-- =====================================================================
-- Returns: the delivery fee refunded for a faulty item now comes from the
-- parcel it was shipped in (each shop charges its own delivery; shops that
-- ship together share one fee), scaled to what the buyer actually paid.
-- Before, it was a share of the whole order's delivery, so returning an
-- item from a free-shipping shop could refund another shop's delivery fee.
-- Older orders without per-shop fees keep the previous rule. Safe to re-run.
-- =====================================================================

begin;

create or replace function public.mivo_return_quote(p_order_id uuid, p_items jsonb, p_reason text)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  o public.orders%rowtype;
  v_items numeric := 0;
  v_goods numeric;
  v_share numeric;
  v_fault boolean;
  v_verified boolean;
  v_shipping numeric := 0;
  v_all_fees numeric := 0;
  v_fee numeric := 0;
  v_already numeric := 0;
  v_refund numeric;
begin
  select * into o from public.orders where id = p_order_id;
  if not found then raise exception 'Order not found'; end if;

  select coalesce(sum(oi.unit_price * least((x.value->>'quantity')::int, oi.quantity)), 0),
         bool_and(coalesce(s.tier, 'standard') = 'direct')
    into v_items, v_verified
  from jsonb_array_elements(p_items) x
  join public.order_items oi on oi.id = (x.value->>'order_item_id')::uuid and oi.order_id = o.id
  left join public.sellers s on s.id = oi.seller_id;

  -- Item price after the order's voucher discount.
  v_items := round(v_items * greatest(o.subtotal - coalesce(o.discount_amount, 0), 0) / nullif(o.subtotal, 0), 2);
  v_items := coalesce(v_items, 0);
  v_goods := greatest(o.total_amount - coalesce(o.shipping_amount, 0), 0);
  v_share := case when v_goods > 0 then least(v_items / v_goods, 1) else 0 end;

  v_fault := p_reason in ('wrong_item','damaged','defective','not_as_described','missing_parts','not_received')
          or (p_reason = 'does_not_fit' and coalesce(v_verified, false));

  if v_fault then
    -- Delivery fee of the parcel(s) the items came in (each shop ships and
    -- charges separately; shops shipping together share one fee), scaled to
    -- what the buyer actually paid for delivery (after free-shipping promos),
    -- in proportion to the part of that parcel being returned.
    select coalesce(sum(coalesce(so.buyer_shipping_fee, 0)), 0) into v_all_fees
      from public.seller_orders so where so.order_id = o.id;
    if v_all_fees > 0 then
      with returned as (
        select coalesce(so.shipping_group, so.id::text) as grp,
               sum(oi.unit_price * least((x.value->>'quantity')::int, oi.quantity)) as value
          from jsonb_array_elements(p_items) x
          join public.order_items oi on oi.id = (x.value->>'order_item_id')::uuid and oi.order_id = o.id
          join public.seller_orders so on so.id = oi.seller_order_id
         group by 1
      ), groups as (
        select coalesce(so.shipping_group, so.id::text) as grp,
               sum(coalesce(so.buyer_shipping_fee, 0)) as fee,
               sum(coalesce(so.subtotal, 0)) as goods
          from public.seller_orders so where so.order_id = o.id
         group by 1
      )
      select coalesce(sum(coalesce(o.shipping_amount, 0) * g.fee / v_all_fees
                          * least(r.value / nullif(g.goods, 0), 1)), 0)
        into v_shipping
        from returned r join groups g using (grp);
      v_shipping := round(coalesce(v_shipping, 0), 2);
    else
      v_shipping := round(coalesce(o.shipping_amount, 0) * v_share, 2);
    end if;
  else
    v_fee := round(coalesce(o.payment_processing_fee_amount, 0) * v_share, 2);
  end if;

  -- Never refund more than what is left of the order.
  select coalesce(sum(coalesce(final_amount, requested_amount)), 0) into v_already
  from public.return_requests
  where order_id = o.id and status in ('refunding','refunded');
  v_refund := least(greatest(v_items + v_shipping - v_fee, 0),
                    greatest(o.total_amount - coalesce(o.cancellation_refund_amount, 0) - v_already, 0));

  return jsonb_build_object(
    'seller_fault', v_fault, 'items_amount', v_items, 'shipping_refund', v_shipping,
    'fee_deduction', v_fee, 'refund_amount', v_refund, 'max_refund',
    greatest(o.total_amount - coalesce(o.cancellation_refund_amount, 0) - v_already, 0));
end;
$$;

revoke all on function public.mivo_return_quote(uuid, jsonb, text) from public, anon, authenticated;

commit;


-- ---------------------------------------------------------------------
-- return-easyparcel.sql
-- ---------------------------------------------------------------------
-- =====================================================================
-- Returns: MIVO decides whose fault it is, and books the return parcel.
--   * The customer's reason is only their claim. When accepting, MIVO
--     (admin) chooses "our fault" (item + its delivery share refunded,
--     return parcel booked and paid by MIVO via EasyParcel) or "not our
--     fault" (change-of-mind rules: no delivery refund, payment fee
--     deducted, customer sends it back at their own cost).
--   * A return booked with EasyParcel stores its AWB / label on the
--     request; the customer drops it off at a courier point and taps
--     "I've dropped it off".
-- Safe to re-run.
-- =====================================================================

begin;

alter table public.return_requests add column if not exists fault_decided_by text;
alter table public.return_requests add column if not exists return_awb_url text;
alter table public.return_requests add column if not exists return_ep_shipment text;
alter table public.return_requests add column if not exists return_label_cost numeric(12,2);
alter table public.return_requests add column if not exists return_booked_at timestamptz;

-- MIVO accepts a request and decides fault. Amounts are recalculated with
-- the same quote rules (faulty vs change of mind).
create or replace function public.return_request_mivo_accept(p_id uuid, p_our_fault boolean, p_note text default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare r public.return_requests%rowtype; v_quote jsonb; v_amount numeric;
begin
  if not public.is_admin() then raise exception 'Only MIVO can decide this'; end if;
  select * into r from public.return_requests where id = p_id for update;
  if not found then raise exception 'Request not found'; end if;
  if r.status not in ('requested', 'mivo_review', 'seller_offer') then raise exception 'This request is already %', r.status; end if;

  v_quote := public.mivo_return_quote(r.order_id, r.items, case when p_our_fault then 'defective' else 'changed_mind' end);
  v_amount := (v_quote->>'refund_amount')::numeric;

  update public.return_requests
     set seller_fault = p_our_fault,
         fault_decided_by = 'mivo',
         items_amount = (v_quote->>'items_amount')::numeric,
         shipping_refund = (v_quote->>'shipping_refund')::numeric,
         fee_deduction = (v_quote->>'fee_deduction')::numeric,
         requested_amount = v_amount,
         status = case when needs_return then 'approved_return' else 'refunding' end,
         final_amount = case when needs_return then null else v_amount end,
         ship_back_by = case when needs_return then now() + interval '7 days' end,
         mivo_note = coalesce(nullif(btrim(coalesce(p_note, '')), ''), mivo_note),
         updated_at = now()
   where id = r.id;
  perform public.mivo_return_log(r.id, 'mivo', case when p_our_fault then 'accepted_our_fault' else 'accepted_not_our_fault' end, p_note, v_amount);
  return jsonb_build_object('refund_amount', v_amount, 'needs_return', r.needs_return, 'our_fault', p_our_fault);
end;
$$;
revoke all on function public.return_request_mivo_accept(uuid, boolean, text) from public, anon;
grant execute on function public.return_request_mivo_accept(uuid, boolean, text) to authenticated;

-- Customer: dropped the pre-booked return parcel off at the courier.
create or replace function public.return_request_customer_dropped(p_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare r public.return_requests%rowtype;
begin
  select * into r from public.return_requests where id = p_id for update;
  if not found or r.customer_id <> auth.uid() then raise exception 'Request not found'; end if;
  if r.status <> 'approved_return' or r.return_tracking is null then raise exception 'This action is not available now'; end if;
  update public.return_requests set status = 'returning', shipped_back_at = now(), updated_at = now() where id = r.id;
  perform public.mivo_return_log(r.id, 'customer', 'shipped_back', coalesce(r.return_courier, '') || ' ' || r.return_tracking, null);
end;
$$;
revoke all on function public.return_request_customer_dropped(uuid) from public, anon;
grant execute on function public.return_request_customer_dropped(uuid) to authenticated;

commit;
notify pgrst, 'reload schema';

